product_sku\') AS exchange_product_sku from `MAPLEMONK._airbyte_raw_s3_pragma_historical` where concat(JSON_VALUE(_airbyte_data, \'$.order_name\') ,JSON_VALUE(_airbyte_data, \'$.product_sku\')) not in (select distinct concat(ordeR_name, sku) from pragma_intermediate_Data) Qualify row_number() over(partition by JSON_VALUE(_airbyte_data, \'$.order_name\'), JSON_VALUE(_airbyte_data, \'$.product_sku\') order by 1 ) = 1 ) select a.order_name , cast(a.ordeR_timestamp as date) order_timestamp , a.sku , d.name , d.category , d.sub_category , d.style_no , REGEXP_REPLACE(d.style_no, r\'/.*$\', \'\') style_group , d.size , a.quantity sales_quantity , case when a.order_Status = \'CANCELLED\' or b.status = \'CANCELED\' then a.quantity else 0 end as cancelled_quantity , case when b.rto_initiated_date is not null then a.quantity else 0 end as RTO_quantity , case when lower(c.return_type) = \'refund\' and sr.status in (\'RETURN PICKED UP\',\'RETURN OUT FOR DELIVERY\',\'RETURN DELIVERED\',\'LOST\',\'RETURN IN TRANSIT\',\'RETURN UNDELIVERED\',\'DELIVERY DELAYED\',\'RETURN OUT FOR DELIVERY\') then a.quantity else 0 end as return_quantity , case when lower(c.return_type) = \'exchange\' and sr.status in (\'RETURN PICKED UP\',\'RETURN OUT FOR DELIVERY\',\'RETURN DELIVERED\',\'LOST\',\'RETURN IN TRANSIT\',\'RETURN UNDELIVERED\',\'DELIVERY DELAYED\',\'RETURN OUT FOR DELIVERY\',\'REACHED AT DESTINATION HUB\') then a.quantity else 0 end as exchange_quantity , c.customer_reason_label from shopify_Data a left join ShiPRocket_Orders b on a.order_name = b.order_name and a.sku = b.channel_sku left join shiprocket_returns sr on a.ordeR_name = sr.ordeR_name and a.sku = sr.channel_sku left join pragma_data c on a.order_name = c.order_name and a.sku = c.sku left join ( select distinct SPLIT(product_code, \'_\')[OFFSET(0)] sku , name , image_url image_link , color style_no , upper(category_name) category , upper(description) sub_category , upper(size) size , mrp , base_price selling_price from maplemonk.banana_club_unicommerce_get_product_master where color <> \'\' ) d on trim(lower(a.sku)) = trim(lower(d.sku)) ;",
